/**
 * Palette engine for the Host half — generated by build/bundle-host.mjs.
 *
 * Concatenates three things that have to agree: the role table, the engine and
 * the Material Color Utilities namespace the engine is constructed over.
 * Regenerate with:
 *
 *   node build/bundle-host.mjs
 */

import * as mcu from './mcu/index.js';

/**
 * Role order shared by the palette generator, the Host palette engine and the
 * runtime.
 *
 * The first 36 entries are read straight off a `DynamicScheme` instance (they
 * are the ARGB getters MaterialDynamicColors derives for every M3 scheme).
 * `surfaceTint` is not a DynamicScheme getter, so the generator reads it from
 * `MaterialDynamicColors.surfaceTint`.
 *
 * The last 8 entries are the semantic pairs Material 3 does not define but a
 * chat application needs (success / warning). They come from fixed tonal
 * palettes so they stay recognisably green / amber through every seed colour.
 */
const ROLE_ORDER = [
  'primary',
  'onPrimary',
  'primaryContainer',
  'onPrimaryContainer',
  'secondary',
  'onSecondary',
  'secondaryContainer',
  'onSecondaryContainer',
  'tertiary',
  'onTertiary',
  'tertiaryContainer',
  'onTertiaryContainer',
  'error',
  'onError',
  'errorContainer',
  'onErrorContainer',
  'background',
  'onBackground',
  'surface',
  'onSurface',
  'surfaceVariant',
  'onSurfaceVariant',
  'outline',
  'outlineVariant',
  'shadow',
  'scrim',
  'inverseSurface',
  'inverseOnSurface',
  'inversePrimary',
  'surfaceDim',
  'surfaceBright',
  'surfaceContainerLowest',
  'surfaceContainerLow',
  'surfaceContainer',
  'surfaceContainerHigh',
  'surfaceContainerHighest',
];

/** Roles that come from fixed tonal palettes rather than from the seed. */
const FIXED_ROLE_ORDER = [
  'success',
  'onSuccess',
  'successContainer',
  'onSuccessContainer',
  'warning',
  'onWarning',
  'warningContainer',
  'onWarningContainer',
];

/** The 36 roles a DynamicScheme exposes directly. */
const SCHEME_ROLE_ORDER = ROLE_ORDER;

/**
 * The single harmony this plugin ships.
 *
 * Material 3 has nine scheme variants; offering all of them turned the settings
 * page into a colour picker and made the palette impossible to describe. Tonal
 * spot is the Material 3 default (the scheme the design system documents first),
 * so it is the only one left. The variant id stays in the data shape because the
 * stored preference and the generated table still key on it.
 */
const VARIANT_ID = 'tonalSpot';

/** material-color-utilities class that implements {@link VARIANT_ID}. */
const VARIANT_CLASS = 'SchemeTonalSpot';

/**
 * The eight Material 3 presets offered in manual mode.
 *
 * Seeds are the tones Material 3 publishes for its own baseline palettes, so a
 * preset lands on the documented `#6750A4` role table rather than on an
 * approximation of it. Automatic mode does not use this list at all — it derives
 * the palette from the operating system accent colour at runtime.
 */
const PRESETS = [
  { id: 'baseline', hex: '#6750a4', label: 'Material baseline' },
  { id: 'blue', hex: '#00639b', label: 'Blue' },
  { id: 'green', hex: '#006e1c', label: 'Green' },
  { id: 'teal', hex: '#006a6a', label: 'Teal' },
  { id: 'orange', hex: '#8e4e00', label: 'Orange' },
  { id: 'pink', hex: '#984061', label: 'Pink' },
  { id: 'red', hex: '#b3261e', label: 'Red' },
  { id: 'blueGrey', hex: '#525e7d', label: 'Blue grey' },
];

/** Preset used whenever the operating system colour cannot be read. */
const DEFAULT_PRESET = 'baseline';

/**
 * Colours the stylesheet needs that are not DSH tokens.
 *
 * The runtime publishes the resolved role of each entry as a `--dsh-m3-*`
 * custom property on `:root`, and the stylesheet references only those
 * properties. Keeping the list here means the generator, the Host engine and the
 * Client all agree on which roles cross the bridge.
 */
const BRIDGE_ROLES = [
  { variable: '--dsh-m3-surface', role: 'surface' },
  { variable: '--dsh-m3-surface-container-lowest', role: 'surfaceContainerLowest' },
  { variable: '--dsh-m3-surface-container-low', role: 'surfaceContainerLow' },
  { variable: '--dsh-m3-surface-container', role: 'surfaceContainer' },
  { variable: '--dsh-m3-surface-container-high', role: 'surfaceContainerHigh' },
  { variable: '--dsh-m3-surface-container-highest', role: 'surfaceContainerHighest' },
  { variable: '--dsh-m3-on-surface', role: 'onSurface' },
  { variable: '--dsh-m3-on-surface-variant', role: 'onSurfaceVariant' },
  { variable: '--dsh-m3-outline', role: 'outline' },
  { variable: '--dsh-m3-outline-variant', role: 'outlineVariant' },
  { variable: '--dsh-m3-primary', role: 'primary' },
  { variable: '--dsh-m3-on-primary', role: 'onPrimary' },
  { variable: '--dsh-m3-primary-container', role: 'primaryContainer' },
  // The selected-row fill and the filled tonal button both need the second
  // container tone; without these two the sheet could only borrow `primary`,
  // which is the wrong role for a container.
  { variable: '--dsh-m3-secondary-container', role: 'secondaryContainer' },
  { variable: '--dsh-m3-on-secondary-container', role: 'onSecondaryContainer' },
  { variable: '--dsh-m3-error', role: 'error' },
  { variable: '--dsh-m3-on-error', role: 'onError' },
  { variable: '--dsh-m3-success', role: 'success' },
  { variable: '--dsh-m3-warning', role: 'warning' },
];


/**
 * Palette engine shared by the build script and the Host half.
 *
 * Every entry point is created by `createPaletteEngine(mcu)`, which takes the
 * Material Color Utilities module object as an argument instead of importing it.
 * That keeps one implementation usable from two very different loaders:
 *
 *   - `build/generate-palettes.mjs` passes the vendored checkout directly.
 *   - `plugin/lib/palette.js` is generated from this file plus
 *     `src/parts/palette-spec.js` and ships the vendored copy in `plugin/lib/mcu/`.
 *
 * The only import below is the role table, and it disappears when the bundles
 * are concatenated (see `build/bundle-client.mjs` and `build/bundle-host.mjs`).
 *
 * All palettes are packed into ONE hex-digit string: 45 roles x 6 digits in
 * `ROLE_ORDER` order with the leading `#` dropped. Slicing a string is cheaper
 * than carrying an object per palette, and it keeps the generated artifact
 * readable.
 */

/** Role name to its slot in a packed palette string. */
const ROLE_INDEX = new Map(
  [...ROLE_ORDER, 'surfaceTint', ...FIXED_ROLE_ORDER].map((role, index) => [role, index]),
);

/** Fixed hues keep success/warning readable regardless of the seed colour. */
const FIXED_PALETTES = {
  success: { hue: 145, chroma: 48 },
  warning: { hue: 75, chroma: 60 },
};

/** Tone choices mirror the M3 primary role pattern. */
const FIXED_TONES = {
  light: { base: 40, onBase: 100, container: 90, onContainer: 10 },
  dark: { base: 80, onBase: 20, container: 30, onContainer: 90 },
};

/**
 * Build the engine over one Material Color Utilities module object.
 *
 * @param mcu the vendored `@material/material-color-utilities` namespace.
 * @returns the palette operations both halves need.
 */
function createPaletteEngine(mcu) {
  const {
    Hct,
    MaterialDynamicColors,
    TonalPalette,
    argbFromHex,
    hexFromArgb,
    SchemeTonalSpot,
  } = mcu;

  const fixedPalettes = {
    success: new TonalPalette(FIXED_PALETTES.success.hue, FIXED_PALETTES.success.chroma),
    warning: new TonalPalette(FIXED_PALETTES.warning.hue, FIXED_PALETTES.warning.chroma),
  };

  function fixedRoleValues(isDark) {
    const tones = FIXED_TONES[isDark ? 'dark' : 'light'];
    const tone = (name, value) => hexFromArgb(fixedPalettes[name].tone(value));
    return [
      tone('success', tones.base),
      tone('success', tones.onBase),
      tone('success', tones.container),
      tone('success', tones.onContainer),
      tone('warning', tones.base),
      tone('warning', tones.onBase),
      tone('warning', tones.container),
      tone('warning', tones.onContainer),
    ];
  }

  function schemeRoleValues(scheme) {
    const values = [];
    for (const role of ROLE_ORDER) {
      const argb = scheme[role];
      if (typeof argb !== 'number') {
        throw new Error('palette engine: scheme is missing role "' + role + '"');
      }
      values.push(hexFromArgb(argb));
    }
    values.push(hexFromArgb(MaterialDynamicColors.surfaceTint.getArgb(scheme)));
    return values;
  }

  /** One scheme's complete role set, packed. */
  function packScheme(scheme, isDark) {
    const values = [...schemeRoleValues(scheme), ...fixedRoleValues(isDark)];
    for (const value of values) {
      if (!/^#[0-9a-f]{6}$/u.test(value)) {
        throw new Error('palette engine: unexpected role value "' + value + '"');
      }
    }
    return values.map((hex) => hex.slice(1)).join('');
  }

  /**
   * Derive both schemes of a seed through the one harmony this plugin ships.
   *
   * Tonal spot is the Material 3 default, so a preset lands on the role table
   * the design system documents rather than on an approximation of it.
   */
  function paletteFromSeed(seedHex) {
    const source = Hct.fromInt(argbFromHex(seedHex));
    return {
      light: packScheme(new SchemeTonalSpot(source, false, 0), false),
      dark: packScheme(new SchemeTonalSpot(source, true, 0), true),
    };
  }

  /** `#rrggbb` for one role out of a packed palette string. */
  function unpack(packed, role) {
    const index = ROLE_INDEX.get(role);
    if (index === undefined) {
      throw new Error('palette engine: unknown role "' + role + '"');
    }
    const start = index * 6;
    return '#' + packed.slice(start, start + 6);
  }

  /** `#rrggbbaa` for one role plus an alpha byte. */
  function unpackAlpha(packed, role, alpha) {
    const byte = Math.round(Math.min(Math.max(alpha, 0), 1) * 255);
    return unpack(packed, role) + byte.toString(16).padStart(2, '0');
  }

  /** Hue and chroma of a colour, used to reject a near-neutral OS accent. */
  function chromaOf(seedHex) {
    return Hct.fromInt(argbFromHex(seedHex)).chroma;
  }

  /** WCAG contrast ratio, used by the build assertions. */
  function contrastRatio(firstHex, secondHex) {
    const luminance = (hex) => {
      const channel = (offset) => {
        const value = parseInt(hex.slice(offset, offset + 2), 16) / 255;
        return value <= 0.03928 ? value / 12.92 : Math.pow((value + 0.055) / 1.055, 2.4);
      };
      return 0.2126 * channel(1) + 0.7152 * channel(3) + 0.0722 * channel(5);
    };
    const a = luminance(firstHex);
    const b = luminance(secondHex);
    const lighter = Math.max(a, b);
    const darker = Math.min(a, b);
    return (lighter + 0.05) / (darker + 0.05);
  }

  return {
    paletteFromSeed,
    packScheme,
    unpack,
    unpackAlpha,
    chromaOf,
    contrastRatio,
  };
}


export { createPaletteEngine, ROLE_ORDER, FIXED_ROLE_ORDER, PRESETS, DEFAULT_PRESET };
export { mcu };
